// H5 library manifest (docs/LIBRARY.md). The library is static content in
// `public/library/index.json`, generated by `scripts/build-library.mjs`, and
// validated here when it loads. Items are data, never code: shapes are
// polygons, and backgrounds, text styles and templates are lists of elements
// placed in fractions of the canvas, so they fit every canvas size.
import { z } from 'zod';

const HEX = /^#[0-9a-fA-F]{6}$/;
const color = z.string().regex(HEX);
const fraction = z.number().finite().min(-1).max(2);
const name = z
  .object({ en: z.string().min(1).max(80), hi: z.string().min(1).max(80) })
  .strict();

/** A gradient fill with 2 to 4 stops (also the `fillGradient` property). */
export const gradientSchema = z
  .object({
    type: z.enum(['linear', 'radial']),
    /** Degrees, 0 = left to right, 90 = top to bottom (linear only). */
    angle: z.number().finite().min(0).max(360),
    stops: z
      .array(
        z.object({ offset: z.number().finite().min(0).max(1), color }).strict(),
      )
      .min(2)
      .max(4),
  })
  .strict();
export type Gradient = z.infer<typeof gradientSchema>;
const paint = z.union([color, gradientSchema]);
export type Paint = z.infer<typeof paint>;

const point = z.tuple([z.number().finite(), z.number().finite()]);
const ring = z.array(point).min(3).max(400);
/** Polygons in a 100 × 100 box (outer ring first, then holes). */
const polygons = z.array(z.array(ring).min(1).max(8)).min(1).max(12);

const box = {
  x: fraction,
  y: fraction,
  w: z.number().finite().min(0.001).max(3),
  h: z.number().finite().min(0.001).max(3),
  rotation: z.number().finite().min(-360).max(360).optional(),
  opacity: z.number().finite().min(0).max(1).optional(),
};
const shapeElement = z
  .object({
    kind: z.literal('shape'),
    ...box,
    shape: z.enum(['rectangle', 'ellipse', 'polygon']),
    polygons: polygons.optional(),
    /** Corner radius as a fraction of the shorter side (rectangles). */
    radius: z.number().finite().min(0).max(0.5).optional(),
    fill: paint,
  })
  .strict();
const text = z
  .object({ en: z.string().min(1).max(200), hi: z.string().min(1).max(200) })
  .strict();
const textElement = z
  .object({
    kind: z.literal('text'),
    ...box,
    text,
    /** Font size as a fraction of the canvas height. */
    size: z.number().finite().min(0.005).max(0.5),
    color,
    font: z.string().max(60).optional(),
    weight: z
      .union([z.literal(400), z.literal(600), z.literal(700)])
      .optional(),
    italic: z.boolean().optional(),
    align: z.enum(['left', 'center', 'right', 'justify']).optional(),
    letterSpacing: z.number().finite().min(-20).max(100).optional(),
    lineHeight: z.number().finite().min(0.5).max(5).optional(),
    textCase: z.enum(['none', 'upper', 'lower', 'title']).optional(),
    decoration: z
      .enum(['none', 'underline', 'line-through', 'underline line-through'])
      .optional(),
  })
  .strict();
const element = z.discriminatedUnion('kind', [shapeElement, textElement]);
export type LibraryElement = z.infer<typeof element>;
export type LibraryTextElement = z.infer<typeof textElement>;
export type LibraryShapeElement = z.infer<typeof shapeElement>;

const base = {
  id: z.string().regex(/^[a-z0-9-]{3,64}$/),
  name,
  tags: z.array(z.string().min(1).max(30)).max(12),
};
const shapeItem = z
  .object({
    ...base,
    type: z.literal('shape'),
    data: z
      .object({
        polygons,
        /** Default size in px on a 1080 px tall canvas (scaled to fit). */
        width: z.number().finite().min(8).max(2000),
        height: z.number().finite().min(8).max(2000),
        fill: paint,
      })
      .strict(),
  })
  .strict();
const backgroundItem = z
  .object({
    ...base,
    type: z.literal('background'),
    data: z.object({ elements: z.array(shapeElement).min(1).max(12) }).strict(),
  })
  .strict();
const textItem = z
  .object({
    ...base,
    type: z.literal('text'),
    data: z.object({ elements: z.array(textElement).min(1).max(4) }).strict(),
  })
  .strict();
const templateItem = z
  .object({
    ...base,
    type: z.literal('template'),
    data: z
      .object({
        background: color,
        elements: z.array(element).min(1).max(24),
      })
      .strict(),
  })
  .strict();
export const libraryItemSchema = z.discriminatedUnion('type', [
  shapeItem,
  backgroundItem,
  textItem,
  templateItem,
]);
export type LibraryItem = z.infer<typeof libraryItemSchema>;
export type LibraryItemType = LibraryItem['type'];

export const libraryManifestSchema = z
  .object({
    version: z.literal(1),
    pack: z.object({ id: z.string(), name }).strict(),
    items: z.array(libraryItemSchema).max(2000),
  })
  .strict()
  .superRefine((manifest, context) => {
    const seen = new Set<string>();
    for (const item of manifest.items) {
      if (seen.has(item.id))
        context.addIssue({
          code: z.ZodIssueCode.custom,
          message: `Duplicate library id ${item.id}`,
        });
      seen.add(item.id);
    }
  });
export type LibraryManifest = z.infer<typeof libraryManifestSchema>;

/** Validates a manifest; throws a readable error when it does not fit. */
export function parseLibrary(value: unknown): LibraryManifest {
  const parsed = libraryManifestSchema.safeParse(value);
  if (!parsed.success) {
    const issue = parsed.error.issues[0]!;
    throw new Error(
      `Library manifest is invalid at ${issue.path.join('.') || '(root)'}: ${issue.message}`,
    );
  }
  return parsed.data;
}
